package it.unipd.dei.webapp.lupus.utils;

import java.security.SecureRandom;
import java.util.UUID;

/**
 * Generates UUIDv7 values (RFC 9562): 48 bits of Unix time in milliseconds, version 7, the RFC variant,
 * and random bits. Ids generated by this class are strictly increasing within the JVM, so they sort by creation time.
 *
 * @author LupusInFabula Group
 * @version 1.0
 * @since 1.0
 */
public final class UuidV7 {

    private static final SecureRandom RANDOM = new SecureRandom();

    /** Last timestamp used (ms). Can run ahead of the clock if more than 4096 ids are asked in one millisecond. */
    private static long lastMillis = -1;

    /** The 12-bit sequence in rand_a, used to keep ids ordered inside the same millisecond. */
    private static int sequence;

    private UuidV7() {
    }

    /**
     * Generates a new UUIDv7.
     *
     * @return A new, unique, time-ordered UUID of version 7.
     */
    public static synchronized UUID generate() {
        final long now = System.currentTimeMillis();
        if (now > lastMillis) {
            lastMillis = now;
            sequence = RANDOM.nextInt(1 << 11); // leaves headroom before the 12-bit limit
        } else if (sequence == 0xFFF) {
            lastMillis++; // sequence exhausted: borrow the next millisecond to stay ordered
            sequence = RANDOM.nextInt(1 << 11);
        } else {
            sequence++;
        }

        final long msb = (lastMillis << 16) | (0x7L << 12) | sequence;
        final long lsb = (RANDOM.nextLong() & 0x3FFFFFFFFFFFFFFFL) | 0x8000000000000000L; // variant 10
        return new UUID(msb, lsb);
    }
}
